from itertools import combinations
rows=['.##.##.','######.','.##.#..','..###..']
S={(r,c) for r,row in enumerate(rows) for c,x in enumerate(row) if x=='#'}
placements=[]
for r in range(4):
 for c in range(6):
  cells={(r+dr,c+dc) for dr in range(2) for dc in range(2)}
  if cells<=S: placements.append(('sq',cells,(r,c)))
# L pieces all missing one of 4 corners
for r in range(3):
 for c in range(6):
  box={(r+dr,c+dc) for dr in range(2) for dc in range(2)}
  for miss in box:
   cells=box-{miss}
   if cells<=S: placements.append(('L',cells,(r,c,miss)))
solutions=[]
def rec(rem,chosen):
 if not rem:
  if sum(p[0]=='sq' for p in chosen)==1: solutions.append(chosen)
  return
 # first uncovered
 x=min(rem)
 for p in placements:
  if x in p[1] and p[1]<=rem: rec(rem-p[1],chosen+[p])
rec(S,[])
len(solutions)
